# Instrument approach procedures: 14 CFR 91.175; AIM 5-4 (categories, MSA, VDP, side-step, circling,
# missed approach, visual and contact approaches, hold in lieu of PT); Instrument Procedures Handbook
# FAA-H-8083-16B ch. 4. ACS area VI.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 3, "Visual references", "At DA you see only the approach lights, not the red terminating or side row bars. How low may you go?",
      ["100 feet above TDZE", "50 feet above TDZE", "200 feet above TDZE"],
      "91.175(c)(3)(i): with the approach lights as the only reference, you may not descend below 100 feet above touchdown zone elevation unless the red terminating bars or red side row bars are also in sight."),
    S(1, 2, "Authorized minimums", "Your authorized DA for an approach is which of these?",
      ["The highest that applies", "The lowest printed on the chart", "The one your instructor endorsed"],
      "91.175(b) makes the authorized DA or MDA the highest of the procedure's, the pilot in command's and the one for the equipment available and used."),
    S(1, 2, "Approach categories", "Your airplane's VREF is 95 knots. Which approach category's minimums apply?",
      ["Category B", "Category A", "Category C"],
      "AIM 5-4-7: Category A is under 91 knots, B is 91 to under 121, C is 121 to under 141. At 95 knots the airplane is Category B."),
    S(1, 2, "Procedure turns", "When may you skip the procedure turn without asking ATC?",
      ["When vectored to the final course", "Whenever you are high on the approach", "When the weather is above 1,000 and 3"],
      "91.175(j): no procedure turn is made when vectored to the final approach course or fix, on a timed approach from a holding fix, or when the route is marked NoPT, unless ATC clears one."),
    S(1, 3, "RVR conversion", "Minimums list RVR 1600, but RVR is not reported for that runway. What visibility applies?",
      ["1/4 statute mile", "1/2 statute mile", "3/4 statute mile"],
      "91.175(h) converts RVR to ground visibility when RVR isn't reported: 1,600 is 1/4 mile, 2,400 is 1/2 mile, 4,000 is 3/4 mile and 5,000 is 1 mile."),
    S(1, 2, "Visual descent point", "A straight-in nonprecision approach shows a VDP. Before reaching it you should:",
      ["Stay at or above the MDA", "Descend below the MDA if you see lights", "Start the missed approach"],
      "AIM 5-4-5: the VDP is where a stabilized visual descent from the MDA can begin. Pilots should not descend below the MDA before reaching it."),
    S(1, 3, "Circling", "While circling at MDA you lose sight of the airport. What do you do first?",
      ["Climbing turn toward the landing runway", "Turn to the missed approach heading at once", "Descend to find the runway lights"],
      "AIM 5-4-21: if visual reference is lost while circling, make an initial climbing turn toward the landing runway and continue until established on the missed approach course."),
    S(1, 2, "Missed approach", "On an ILS you reach DA without the visual references 91.175 requires. What must you do?",
      ["Fly the missed approach", "Level off at DA and keep looking", "Continue to the runway threshold"],
      "91.175(e) requires an immediate missed approach on reaching the DA or MAP without the required visual references and flight visibility."),
    # ---------- Practice Test 2 ----------
    S(2, 2, "Approach types", "Which approach minimums are published as a DA, not an MDA?",
      ["LPV", "LNAV", "Circling"],
      "LPV and LNAV/VNAV are approaches with vertical guidance and use a decision altitude. LNAV and circling minimums are minimum descent altitudes."),
    S(2, 2, "Visual approach", "For ATC to issue a visual approach, what weather must the airport report?",
      ["Ceiling 1,000 feet, visibility 3 miles", "Ceiling 500 feet, visibility 1 mile", "Ceiling 3,000 feet, visibility 5 miles"],
      "AIM 5-4-23: a visual approach needs a reported ceiling of at least 1,000 feet and visibility of at least 3 miles, with the airport or the preceding aircraft in sight."),
    S(2, 3, "Visual approach", "Flying a visual approach, what is your flight plan status?",
      ["Still IFR, under ATC control", "VFR until you land", "Cancelled once you see the field"],
      "AIM 5-4-23: a visual approach is an IFR procedure flown in visual conditions. You stay on your IFR flight plan and under ATC control."),
    S(2, 2, "Minimum safe altitude", "What does the MSA on an approach chart provide?",
      ["1,000 feet of obstacle clearance", "Assured navigation signal reception", "A vectoring altitude for ATC"],
      "AIM 5-4-5: the MSA, for emergency use, gives 1,000 feet of clearance over obstacles, normally within 25 NM, but doesn't assure navigation signals."),
    S(2, 3, "Approach categories", "A Category B airplane must circle at 145 knots in gusty wind. Which minimums should it use?",
      ["Category D", "Category B", "Category C"],
      "AIM 5-4-7 says to use the minimums of the category that matches the speed flown. At 145 knots that is Category D (141 to under 166)."),
    S(2, 2, "Landing", "At MDA the runway is in sight, but flight visibility is below the chart value. May you land?",
      ["No, visibility must be at minimums", "Yes, once the runway is in sight", "Yes, if the ceiling is above the MDA"],
      "91.175(d) bars landing when the flight visibility is less than the visibility in the approach procedure being used."),
    S(2, 2, "Side-step", "Cleared for an approach with a side-step to the parallel runway, when do you begin it?",
      ["As soon as the runway is in sight", "Only after the missed approach point", "When ATC calls the side-step"],
      "AIM 5-4-19: pilots begin the side-step as soon as possible after the runway or runway environment is in sight, still meeting any stepdown altitudes."),
    S(2, 3, "Hold in lieu of PT", "Flying a hold-in-lieu-of-procedure-turn, what must you not exceed?",
      ["The charted leg length or time", "Three circuits of the holding pattern", "The MSA for that sector"],
      "AIM 5-4-9: in a hold in lieu of a procedure turn, fly the pattern as depicted and don't exceed the specified leg length or timing. Holding speed limits apply."),
    # ---------- Drill only ----------
    S(0, 2, "Stepdown fixes", "On a nonprecision final with a stepdown fix, when may you descend to the MDA?",
      ["After passing the stepdown fix", "Right after the final approach fix", "Once the airport is in sight"],
      "Each stepdown altitude protects against an obstacle before its fix. Descend to the next lower altitude, or MDA, only after passing the stepdown fix."),
    S(0, 3, "Timed approach", "The FAF is 4.5 NM from the MAP and your groundspeed is 90 knots. How long to the MAP?",
      ["3 minutes", "6 minutes", "4 minutes 30 seconds"],
      "At 90 knots you cover 1.5 NM per minute: 4.5 / 1.5 = 3 minutes from the FAF to the MAP."),
    S(0, 3, "Descent rate", "About what descent rate holds a 3-degree glide path at 90 knots groundspeed?",
      ["About 480 fpm", "About 380 fpm", "About 320 fpm"],
      "A 3-degree path is about 318 feet per NM. At 90 knots, 1.5 NM per minute, that is about 477, so about 480 fpm; a quick check is groundspeed x 5, or 450."),
    S(0, 2, "Glide slope out", "The glide slope fails on an ILS. Which minimums do you use?",
      ["The LOC minimums as an MDA", "The ILS DA plus 200 feet", "The circling DA for the runway"],
      "Without the glide slope the approach becomes a localizer approach, flown to the published LOC minimums, an MDA, with stepdown altitudes observed."),
    S(0, 2, "Approach types", "Which approach is a precision approach?",
      ["ILS", "LNAV/VNAV", "VOR/DME"],
      "An ILS is a precision approach. LNAV/VNAV and LPV are approaches with vertical guidance (APV), and VOR/DME is nonprecision."),
    S(0, 2, "Procedure turns", "Where must a procedure turn be completed?",
      ["On the charted side, within the distance", "Anywhere within 25 NM of the fix", "On either side, at or below the MSA"],
      "The profile shows the distance within which the procedure turn must be completed, usually 10 NM, and the maneuver stays on the side depicted."),
    S(0, 3, "Visual references", "Which is NOT one of the visual references 91.175 lists for descending below DA?",
      ["Taxiway centerline lights", "Threshold markings", "Visual glideslope indicator"],
      "91.175(c)(3) lists the approach lights, threshold, its markings and lights, REILs, visual glideslope indicator, touchdown zone and its lights, and the runway with its markings and lights. Taxiway lights aren't on the list."),
    S(0, 2, "Circling", "When may you leave the MDA while circling to land?",
      ["When a normal descent is possible", "As soon as any airport light is seen", "After one full circuit of the field"],
      "91.175(c)(1) allows descent below MDA only when the airplane is continuously in a position to descend to the intended runway at a normal rate with normal maneuvers."),
    S(0, 2, "Visual approach", "On a visual approach, what must you have in sight?",
      ["The airport or the aircraft ahead", "The runway centerline lights", "The final approach fix marker"],
      "AIM 5-4-23: a visual approach needs the airport or the preceding identified aircraft in sight, and you proceed clear of clouds."),
    S(0, 3, "GPS approach", "If you don't arm approach mode, what does the GPS CDI do inside 30 NM?",
      ["Stays at en route scaling", "Switches to 0.3 NM at once", "Shows a VOR back course"],
      "AIM 1-1: without arming, the receiver won't change from the en route 5 NM sensitivity to the 1 NM terminal sensitivity, so the CDI stays far too coarse."),
    S(0, 2, "Approach categories", "What speed sets an airplane's approach category?",
      ["VREF, or 1.3 VSO if none", "Its normal cruise speed", "Its maximum flap extension speed"],
      "AIM 5-4-7: the category depends on VREF, or 1.3 times the stall speed in landing configuration at maximum landing weight if no VREF is given."),
]
